from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import wait

# Set up all devices.
prime_hub = PrimeHub()
Left = Motor(Port.A, Direction.CLOCKWISE)
Right = Motor(Port.B, Direction.COUNTERCLOCKWISE)
drive_base = DriveBase(Left, Right, 82, 128)


# The main program starts here.
# Default Turn Rate
drive_base.turn(360)
print(drive_base.angle())
wait(1000)
# Turn Faster
drive_base.reset(0, 0)
drive_base.settings(turn_rate=100)
drive_base.turn(360)
print(drive_base.angle())
wait(1000)
# Turn and Accelerate faster
drive_base.reset(0, 0)
drive_base.settings(turn_acceleration=2000)
drive_base.turn(360)
print(drive_base.angle())
